                case MetaAttribute.Epoch: return "";
                case MetaAttribute.TimeUnit: return "";
                case MetaAttribute.SemanticType: return "";
                case MetaAttribute.Presence: return "required";
            }

            return "";
        }

        public const int InstrumentReqIDHeaderSize = 1;
        
        public int InstrumentReqIDLength()
        {
            _buffer.CheckLimit(_parentMessage.Limit + 1);
            return (int)_buffer.Uint8Get(_parentMessage.Limit);
        }

        public int GetInstrumentReqID(byte[] dst, int dstOffset, int length) =>
            GetInstrumentReqID(new Span<byte>(dst, dstOffset, length));

        public int GetInstrumentReqID(Span<byte> dst)
        {
            const int sizeOfLengthField = 1;
            int limit = _parentMessage.Limit;
            _buffer.CheckLimit(limit + sizeOfLengthField);
            int dataLength = (int)_buffer.Uint8Get(limit);
            int bytesCopied = Math.Min(dst.Length, dataLength);
            _parentMessage.Limit = limit + sizeOfLengthField + dataLength;
            _buffer.GetBytes(limit + sizeOfLengthField, dst.Slice(0, bytesCopied));

            return bytesCopied;
        }
        
        // Allocates and returns a new byte array
        public byte[] GetInstrumentReqIDBytes()
        {
            const int sizeOfLengthField = 1;
            int limit = _parentMessage.Limit;
            _buffer.CheckLimit(limit + sizeOfLengthField);
            int dataLength = (int)_buffer.Uint8Get(limit);
            byte[] data = new byte[dataLength];
            _parentMessage.Limit = limit + sizeOfLengthField + dataLength;
            _buffer.GetBytes(limit + sizeOfLengthField, data);

            return data;
        }

        public int SetInstrumentReqID(byte[] src, int srcOffset, int length) =>
            SetInstrumentReqID(new ReadOnlySpan<byte>(src, srcOffset, length));

        public int SetInstrumentReqID(ReadOnlySpan<byte> src)
        {
            const int sizeOfLengthField = 1;
            int limit = _parentMessage.Limit;
            _parentMessage.Limit = limit + sizeOfLengthField + src.Length;
            _buffer.Uint8Put(limit, (byte)src.Length);
            _buffer.SetBytes(limit + sizeOfLengthField, src);

            return src.Length;
        }

        public string GetInstrumentReqID()
        {
            const int sizeOfLengthField = 1;
            int limit = _parentMessage.Limit;
            _buffer.CheckLimit(limit + sizeOfLengthField);
            int dataLength = (int)_buffer.Uint8Get(limit);
            _parentMessage.Limit = limit + sizeOfLengthField + dataLength;
            return _buffer.GetStringFromBytes(InstrumentReqIDResolvedCharacterEncoding, limit + sizeOfLengthField, dataLength);
        }

        public void SetInstrumentReqID(string value)
        {
            var encoding = InstrumentReqIDResolvedCharacterEncoding;
            const int sizeOfLengthField = 1;
            int limit = _parentMessage.Limit;
            int byteCount = _buffer.SetBytesFromString(encoding, value, limit + sizeOfLengthField);
            _parentMessage.Limit = limit + sizeOfLengthField + byteCount;
            _buffer.Uint8Put(limit, (byte)byteCount);
        }

        public override string ToString()
        {
            var sb = new StringBuilder(100);
            var m = new InstrumentList();
            m.WrapForDecode(_buffer, _offset, _actingBlockLength, _actingVersion);
            m.BuildString(sb);
            return sb.ToString();
        }

        internal void BuildString(StringBuilder builder)
        {
            if (_buffer == null)
            {
                throw new ArgumentNullException("_buffer");
            }

            int originalLimit = this.Limit;
            this.Limit = _offset + _actingBlockLength;
            builder.Append("[InstrumentList](sbeTemplateId=");
            builder.Append(InstrumentList.TemplateId);
            builder.Append("|sbeSchemaId=");
            builder.Append(InstrumentList.SchemaId);
            builder.Append("|sbeSchemaVersion=");
            if (_parentMessage._actingVersion != InstrumentList.SchemaVersion)
            {
                builder.Append(_parentMessage._actingVersion);
                builder.Append('/');
            }
            builder.Append(InstrumentList.SchemaVersion);
            builder.Append("|sbeBlockLength=");
            if (_actingBlockLength != InstrumentList.BlockLength)
            {
                builder.Append(_actingBlockLength);
                builder.Append('/');
            }
            builder.Append(InstrumentList.BlockLength);
            builder.Append("):");

            builder.Append("RelatedSym=[");
            var relatedSym = this.RelatedSym;
            if (relatedSym.Count > 0)
            {
                var first = true;
                while (relatedSym.HasNext)
                {
                    if (!first)
                    {
                        builder.Append(',');
                    }
                    first = false;
                    relatedSym.Next().BuildString(builder);
                }
            }
            builder.Append("]");
            builder.Append('|');
            builder.Append("InstrumentReqID=");
            builder.Append('\'').Append(GetInstrumentReqID()).Append('\'');

            this.Limit = originalLimit;

        }
    }
